// Executar em: Run Once for All Items
const inputItems = $input.all();

const out = [];

for (const it of inputItems) {
  const j = it.json ?? {};

  // 1) Tenta output.message (objeto), 2) output (string), 3) message (string)
  let text =
    (typeof j.output?.message === 'string' && j.output.message) ||
    (typeof j.output === 'string' && j.output) ||
    (typeof j.message === 'string' && j.message) ||
    '';

  // Normaliza quebras de linha e evita parágrafos vazios
  const paragraphs = text
    .replace(/\r\n/g, '\n')
    .trim()
    .split(/\n{2,}/)
    .filter(p => p.trim().length);

  // Para cada parágrafo, cria um item de saída
  paragraphs.forEach((p, idx) => {
    out.push({
      json: {
        key: `paragraph${idx + 1}`,
        paragraph: p
      }
    });
  });
}

return out;

